public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    backtrack(new ArrayList<>(), new boolean[nums.length], nums, res);
    return res;
}

private void backtrack(List<Integer> current, boolean[] used, int[] nums, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (!used[i]) {
            used[i] = true;
            current.add(nums[i]);
            backtrack(current, used, nums, res);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the maximum length among all strings
    int maxLen = 0;
    for (String s : strings) {
        if (s != null) {
            maxLen = Math.max(maxLen, s.length());
        }
    }
    // If no string has positive length, no substring possible
    if (maxLen == 0) {
        return 0;
    }
    String first = strings.get(0);
    if (first == null) {
        first = "";
    }
    for (int len = maxLen; len >= 1; len--) {
        // Gather unique substrings of length len from the first string
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= first.length(); i++) {
            candidates.add(first.substring(i, i + len));
        }
        // For each candidate, check all strings
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
            boolean ok = true;
            for (String t : strings) {
                if (t == null) {
                    ok = false;
                    break;
                }
                if (!t.contains(cand) && !t.contains(rev)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null) {
        return 0;
    }
    int rows = grid.length;
    if (rows == 0) {
        return 0;
    }
    boolean[][] visited = new boolean[rows][];
    for (int r = 0; r < rows; r++) {
        visited[r] = new boolean[grid[r].length];
    }

    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        int cols = grid[r].length;
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                java.util.Stack<int[]> stack = new java.util.Stack<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;

                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int pr = pos[0];
                    int pc = pos[1];

                    for (int d = 0; d < 8; d++) {
                        int nr = pr + dr[d];
                        int nc = pc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
                            if (!visited[nr][nc] && grid[nr][nc] == '@') {
                                visited[nr][nc] = true;
                                stack.push(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    return count;
}

