                java.time.format.DateTimeFormatter.ofPattern("MM dd yyyy").withLocale(java.util.Locale.ENGLISH);
        java.time.LocalDate localDate = java.time.LocalDate.parse(date, inputFormatter);

        java.time.format.DateTimeFormatter outputFormatter =
                java.time.format.DateTimeFormatter.ofPattern("MMMM d, yyyy").withLocale(java.util.Locale.ENGLISH);
