    }
}

public int[] twoSum(int[] nums, int target) {
    if (nums == null || nums.length < 2) {
        throw new IllegalArgumentException("Input array must contain at least two elements");
    }
    java.util.Map<Integer, Integer> indexByValue = new java.util.HashMap<>();
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        Integer complementIndex = indexByValue.get(complement);
        if (complementIndex != null) {
            return new int[]{complementIndex, i};
        }
        indexByValue.put(nums[i], i);
    }
    throw new IllegalArgumentException("No two sum solution exists");
}

public int search(int[] nums, int target) {
    if (nums == null || nums.length == 0) {
        return -1;
    }
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        // Determine which side is properly sorted
        if (nums[left] <= nums[mid]) {
            // Left side is sorted
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // Right side is sorted
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be empty");
    }
    int n = arr.length;
    // number of elements to trim from each side (5%)
    int k = (int) Math.floor(n * 0.05);
    // Sort the array to remove the extremes
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = k; i < n - k; i++) {
        sum += arr[i];
    }
    // number of remaining elements
    int remaining = n - 2 * k;
    return sum / (double) remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0) return false;
    if (arr.length % 2 != 0) return false; // cannot form pairs

    if (k <= 0) return false; // divisor must be positive

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) return false;

    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // Check other remainders
    for (int r = 1; r < k; r++) {
        // Skip the complementary pair already processed
        if (r == k - r) continue; // this case handled above
        if (freq[r] != freq[k - r]) return false;
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.ArrayList<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    int[] time = {0};
    dfs(0, -1, adj, hasApple, time);
    return time[0];
}

private boolean dfs(int node, int parent, java.util.ArrayList<Integer>[] adj, boolean[] hasApple, int[] time) {
    boolean has = hasApple[node];
    for (int neigh : adj[node]) {
        if (neigh == parent) {
            continue;
        }
        boolean childHas = dfs(neigh, node, adj, hasApple, time);
        if (childHas) {
            time[0] += 2;
            has = true;
        }
    }
    return has;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int total = 0;
    for (int num : nums) total += num;
    int maxk = n / 2;
    @SuppressWarnings("unchecked")
    java.util.Set<Integer>[] sums = new java.util.HashSet[maxk + 1];
    for (int i = 0; i <= maxk; i++) {
        sums[i] = new java.util.HashSet<>();
    }
    for (int val : nums) {
        for (int k = maxk; k >= 1; k--) {
            java.util.Set<Integer> prev = sums[k - 1];
            java.util.Set<Integer> current = sums[k];
            for (int s : prev) {
                current.add(s + val);
            }
        }
    }
    for (int k = 1; k <= maxk; k++) {
        if ((total * k) % n == 0) {
            int target = (total * k) / n;
            if (sums[k].contains(target)) return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start from step 1 (outside the array) and reach the top with no cost
        return 0;
    }
    int dpPrevPrev = cost[0];   // dp[0]
    int dpPrev = cost[1];       // dp[1]
    int dpCurr = 0;
    for (int i = 2; i < n; i++) {
        dpCurr = cost[i] + Math.min(dpPrev, dpPrevPrev);
        dpPrevPrev = dpPrev;
        dpPrev = dpCurr;
    }
    // The top can be reached from step n-1 or n-2
    return Math.min(dpPrev, dpPrevPrev);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }
    String[] morse = {
        ".-","-...","-.-.","-..",".","..-.", "--.", "....", "..",   // a-i
        ".---","-.-",".-..","--","-.", "---", ".--.", "--.-", ".-.", // j-r
        "...","-","..-","...-",".--","-..-","-.--","--.."          // s-z
    };
    java.util.Set<String> unique = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            continue;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);
            if (c >= 'a' && c <= 'z') {
                sb.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(morse[c - 'A']);
            }
        }
        unique.add(sb.toString());
    }
    return unique.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) return false;
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k; // total possible binary strings of length k
    if (total > n - k + 1) return false; // not enough substrings to cover all possibilities
    boolean[] seen = new boolean[total];
    int window = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        window = (window << 1) | (s.charAt(i) - '0');
    }
    seen[window] = true;
    int count = 1;
    // Slide the window through the string
    int mask = total - 1; // to keep only k bits
    for (int i = k; i < n; i++) {
        window = ((window << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[window]) {
            seen[window] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

