public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int leftNeeded = 0; // count of '(' that need a matching ')'
    int insertions = 0; // count of ')' that need a preceding '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            leftNeeded++;
        } else if (c == ')') {
            if (leftNeeded == 0) {
                // No matching '(', need to insert one
                insertions++;
            } else {
                leftNeeded--;
            }
        }
    }
    // Any remaining unmatched '(' need a ')'
    insertions += leftNeeded;
    return insertions;
}

