public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    long maxEnding = 0;
    long maxOverall = nums[0];
    long minEnding = 0;
    long minOverall = nums[0];
    for (int num : nums) {
        maxEnding = Math.max(num, maxEnding + num);
        maxOverall = Math.max(maxOverall, maxEnding);
        minEnding = Math.min(num, minEnding + num);
        minOverall = Math.min(minOverall, minEnding);
    }
    long maxAbs = Math.max(Math.abs(maxOverall), Math.abs(minOverall));
    return (int) maxAbs;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    java.util.List<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (fib.get(fib.size() - 1) <= k) {
        int size = fib.size();
        int next = fib.get(size - 1) + fib.get(size - 2);
        fib.add(next);
    }

    int count = 0;
    int remaining = k;
    // Greedy: pick the largest Fibonacci number <= remaining
    for (int i = fib.size() - 1; i >= 0 && remaining > 0; i--) {
        while (fib.get(i) <= remaining) {
            remaining -= fib.get(i);
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Lists to store factors found below and above the square root
    java.util.List<Integer> lower = new java.util.ArrayList<>();
    java.util.List<Integer> upper = new java.util.ArrayList<>();

    // Find all factor pairs
    for (int i = 1; i * (long) i <= n; i++) {
        if (n % i == 0) {
            lower.add(i);                     // Small factor
            if (i != n / i) {
                upper.add(n / i);            // Corresponding large factor
            }
        }
    }

    // The large factors are in descending order; reverse them
    java.util.Collections.reverse(upper);

    int totalFactors = lower.size() + upper.size();
    if (k > totalFactors) {
        return -1; // Not enough factors
    }

    if (k <= lower.size()) {
        return lower.get(k - 1);
    } else {
        // Adjust index for the upper list
        return upper.get(k - lower.size() - 1);
    }
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (char c : s.toCharArray()) {
        int length = stack.length();
        if (length > 0) {
            char top = stack.charAt(length - 1);
            // Check if c and top are the same letter of opposite cases
            if (Math.abs(c - top) == 32) {
                stack.deleteCharAt(length - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] best = new int[1];
    dfs(0, new java.util.HashSet<>(), 0, best, s);
    return best[0];
}

private void dfs(int idx, java.util.Set<String> used, int count, int[] best, String s) {
    int n = s.length();
    if (idx == n) {
        best[0] = Math.max(best[0], count);
        return;
    }
    for (int end = idx + 1; end <= n; end++) {
        String sub = s.substring(idx, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(end, used, count + 1, best, s);
            used.remove(sub);
        }
    }
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        if (log.equals("../")) {
            depth = Math.max(depth - 1, 0);
        } else if (log.equals("./")) {
            // no operation needed
        } else if (log.endsWith("/")) {
            depth++;
        } // ignore other invalid entries
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    if (k < n || k > n * 26) {
        throw new IllegalArgumentException("k must be between " + n + " and " + (n * 26));
    }
    int remaining = k - n; // extra value beyond all 'a's
    char[] result = new char[n];
    for (int i = n - 1; i >= 0; i--) {
        if (remaining == 0) {
            result[i] = 'a';
            continue;
        }
        int add = Math.min(25, remaining); // we can add at most 25 to 'a' -> 'z'
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

