public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        int lastDigit = (int) (current % 10);
        if (lastDigit > 0) {
            long next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower   = n % factor;
        long current = (n / factor) % 10;
        long higher  = n / (factor * 10);

        if (current == 0) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num == 0) {
        return 0;
    }
    while (num > 9) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] left = new int[m][n];
    int[][] up = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(left[i][j], up[i][j]),
                                         Math.max(diag[i][j], anti[i][j]));
                if (localMax > max) {
                    max = localMax;
                }
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    do {
        sb.append(value % 10);
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    } while (value > 0);
    if (negative) sb.append('-');
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);
    int maxVal = A[n - 1];
    int maxSum = maxVal + maxVal;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 2; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[1 << n][n];
    for (int[] row : memo) {
        java.util.Arrays.fill(row, -1);
    }
    class Solver {
        int dfs(int lastIdx, int mask) {
            if (mask == fullMask) return 1;
            int memoVal = memo[mask][lastIdx];
            if (memoVal != -1) return memoVal;
            int ans = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (!isSquare[A[lastIdx] + A[next]]) continue;
                if (next > 0 && A[next] == A[next - 1] && (mask & (1 << (next - 1))) == 0) continue;
                ans += dfs(next, mask | (1 << next));
            }
            memo[mask][lastIdx] = ans;
            return ans;
        }
    }
    Solver solver = new Solver();
    int total = 0;
    for (int start = 0; start < n; start++) {
        if (start > 0 && A[start] == A[start - 1]) continue;
        int firstMask = 1 << start;
        total += solver.dfs(start, firstMask);
    }
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    int row = 0, col = 0;
    boolean up = true;

    while (index < m * n) {
        res[index++] = mat[row][col];
        if (up) {
            if (col == n - 1) { // hit right edge
                row++;
                up = false;
            } else if (row == 0) { // hit top edge
                col++;
                up = false;
            } else { // move up-right
                row--;
                col++;
            }
        } else { // down-left
            if (row == m - 1) { // hit bottom edge
                col++;
                up = true;
            } else if (col == 0) { // hit left edge
                row++;
                up = true;
            } else { // move down-left
                row++;
                col--;
            }
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] c = String.valueOf(n).toCharArray();
    int[] d = new int[c.length];
    for (int i = 0; i < c.length; i++) {
        d[i] = c[i] - '0';
    }

    // Find the first index from the end where d[i] < d[i+1]
    int i = d.length - 2;
    while (i >= 0 && d[i] >= d[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit greater than d[i] in the suffix
    int j = d.length - 1;
    while (d[j] <= d[i]) {
        j--;
    }

    // Swap
    int tmp = d[i];
    d[i] = d[j];
    d[j] = tmp;

    // Reverse the suffix
    int l = i + 1;
    int r = d.length - 1;
    while (l < r) {
        tmp = d[l];
        d[l] = d[r];
        d[r] = tmp;
        l++;
        r--;
    }

    // Convert back to integer, check for overflow
    long result = 0;
    for (int val : d) {
        result = result * 10 + val;
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }
    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    build(n, n, result);
    return result;
}

private static void build(int current, int total, List<String> result) {
    if (current == 0) {
        result.add("");
        return;
    }
    if (current == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return;
    }

    List<String> previous = new ArrayList<>();
    build(current - 2, total, previous);
    List<String[]> pairs = List.of(
            new String[]{"0", "0"},
            new String[]{"1", "1"},
            new String[]{"6", "9"},
            new String[]{"8", "8"},
            new String[]{"9", "6"}
    );
    for (String[] p : pairs) {
        // Skip leading zeros for the outermost pair unless the total length is 1
        if (current == total && p[0].equals("0")) {
            continue;
        }
        for (String inner : previous) {
            result.add(p[0] + inner + p[1]);
        }
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }

    // Check all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];

    int areaTwice = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);
    return areaTwice != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s){
    if (s == null || s.isEmpty()){
        return 0;
    }
    int maxLength = 1;
    int currentLength = 1;
    for (int i = 1; i < s.length(); i++){
        if (s.charAt(i) == s.charAt(i - 1)){
            currentLength++;
        } else {
            if (currentLength > maxLength){
                maxLength = currentLength;
            }
            currentLength = 1;
        }
    }
    if (currentLength > maxLength){
        maxLength = currentLength;
    }
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(Math.max(n, 0));
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> result) {
    if (current > n) {
        return;
    }
    result.add(current);
    if (current <= n / 10) {
        for (int i = 0; i <= 9; i++) {
            dfs(current * 10 + i, n, result);
        }
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    try {
        java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return sum;
    } catch (Exception e) {
        // In case of any unexpected error, return 0
        return 0;
    }
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int best = Integer.MAX_VALUE;
        for (int s = 1; s * s <= i; s++) {
            int square = s * s;
            int cand = dp[i - square] + 1;
            if (cand < best) {
                best = cand;
            }
        }
        dp[i] = best;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        for (int j = word.length() - 1; j >= 0; j--) {
            result.append(word.charAt(j));
        }
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
